import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as t,a,b as s}from"./chunks/M-S-SY3.DDtr6WYL.js";import{_ as r}from"./chunks/M-S-SY2.BC5ErUru.js";import{_ as n}from"./chunks/DIS.DdpTdGGD.js";import{_ as p,o as l,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const k=JSON.parse('{"title":"Configurer un abonné Sync","description":"","frontmatter":{"source_hash":"2d97e8913b","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/syncsetup.md","filePath":"fr/use/syncsetup.md"}'),m={name:"fr/use/syncsetup.md"};function u(h,o,b,g,f,y){return l(),c("div",null,[...o[0]||(o[0]=[d('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip+ Synchronisation</p></div><div class="warning custom-block"><p class="custom-block-title">Ancienne synchronisation xDrip</p><p>En juillet 2024, Google a arrêté l&#39;<a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">API Firebase</a> obsolète que xDrip utilisait pour la synchronisation xDrip.<br> Mettez à jour xDrip vers une version du <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">23 juillet 2024</a> ou plus récente pour utiliser l&#39;ancienne méthode de synchronisation.<br> Il est recommandé de mettre à jour xDrip au moins vers la dernière version publiée.</p></div><p>xDrip propose un mécanisme unique de synchronisation en temps réel entre appareils Android, qui rend le partage des glycémies et des traitements aussi simple que possible.</p><br><p><a href="https://www.youtube.com/watch?v=LcgjfbYcWkE" target="_blank" rel="noreferrer">Voici la vidéo de référence d&#39;origine</a>.</p><h3 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Les <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">services Google Play</a> sont indispensables pour utiliser cette fonction. Assurez-vous qu&#39;ils sont présents, activés et non soumis à l&#39;optimisation de la batterie.</p></div><p>Le téléphone xDrip principal est l&#39;appareil qui reçoit réellement les glycémies directement d&#39;un capteur, d&#39;un transmetteur ou d&#39;une application.<br> Faire d&#39;un appareil abonné le principal de la synchronisation xDrip n&#39;apporte pas grand-chose, sauf si l&#39;appareil abonné ne peut pas utiliser la même source de données.</p><p>Votre principal doit recevoir les données de manière fiable. Si vous n&#39;avez pas de données sur votre abonné, commencez toujours par dépanner le principal.</p><h2 id="setup-master" tabindex="-1">Configurer le principal <a class="header-anchor" href="#setup-master" aria-label="Permalink to &quot;Configurer le principal {#setup-master}&quot;">​</a></h2><p>Faites du téléphone qui reçoit la source de données principale le maître (cochez la case) :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip+ Synchronisation</p><p>    <strong>Soyez maître pour les Abonnés <span class="symbol" style="float:right;"><img src="'+i+'" style="zoom:75%;">  </span></strong></p></div><br><h3 id="copy-the-sync-key" tabindex="-1">Copier la clé de synchronisation <a class="header-anchor" href="#copy-the-sync-key" aria-label="Permalink to &quot;Copier la clé de synchronisation {#copy-the-sync-key}&quot;">​</a></h3><h4 id="option-1-recommended" tabindex="-1">Option 1 (recommandée) <a class="header-anchor" href="#option-1-recommended" aria-label="Permalink to &quot;Option 1 (recommandée) {#option-1-recommended}&quot;">​</a></h4><p>Sur le téléphone principal, affichez le QR code de la clé de synchronisation :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"> Affichage QR codes</p><div style="background-color:gray;color:white;text-align:center;">  XDRIP+ CLÉS DE SÉCURITÉ SEULEMENT </div></div><p>Laissez le téléphone principal sur cette image pour le moment.</p><img src="'+t+'" style="zoom:75%;"><h5 id="option-1-bis-follower-phone-cannot-read-the-qr-code" tabindex="-1">Option 1 bis (le téléphone abonné ne peut pas lire le QR code) <a class="header-anchor" href="#option-1-bis-follower-phone-cannot-read-the-qr-code" aria-label="Permalink to &quot;Option 1 bis (le téléphone abonné ne peut pas lire le QR code) {#option-1-bis-follower-phone-cannot-read-the-qr-code}&quot;">​</a></h5><p>Faites une capture d&#39;écran du QR code et envoyez-la au téléphone abonné (MMS, WhatsApp, envoi sur Google Cloud, ...).</p><h4 id="option-2-complicated" tabindex="-1">Option 2 (compliquée) <a class="header-anchor" href="#option-2-complicated" aria-label="Permalink to &quot;Option 2 (compliquée) {#option-2-complicated}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip+ Synchronisation</p><p>    <strong>Clé de sécurité de groupe de dispositifs</strong></p></div><img src="'+r+'" style="zoom:75%;"><br><h2 id="setup-follower" tabindex="-1">Configurer l&#39;abonné <a class="header-anchor" href="#setup-follower" aria-label="Permalink to &quot;Configurer l&#39;abonné {#setup-follower}&quot;">​</a></h2><p>Faites de tous les autres téléphones des abonnés (décochez la case) :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip+ Synchronisation</p><p>    <strong>Soyez maître pour les Abonnés <span class="symbol" style="float:right;"><img src="'+n+'" style="zoom:75%;">  </span></strong></p></div><br><p>Définissez la source de données de l&#39;abonné :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   xDrip Sync Follower</p></div><p>En savoir plus sur la source de données <a href="./../install/xdripfollower.html">xDrip Sync Follower</a>.</p><br><div class="warning custom-block"><p class="custom-block-title">Utiliser xDrip Cloud doit être réglé de la même façon sur tous les téléphones</p><p>Principal et abonnés. Soit activé pour tous, soit désactivé pour tous.</p></div><div class="admonition xdripitem"><p class="admonition-title">Utiliser xDrip Cloud</p><p> Utilisez les nouveaux serveurs cloud de xDrip+. Les maîtres et les abonnés doivent tous avoir ce paramètre défini à l&#39;identique.</p></div><p>Il est recommandé d&#39;activer <a href="./sync.html#use-xdrip-cloud">Utiliser xDrip Cloud</a> sur tous les appareils : c&#39;est la méthode la plus pérenne.</p><h3 id="copy-the-sync-key-from-the-master" tabindex="-1">Copier la clé de synchronisation depuis le principal <a class="header-anchor" href="#copy-the-sync-key-from-the-master" aria-label="Permalink to &quot;Copier la clé de synchronisation depuis le principal {#copy-the-sync-key-from-the-master}&quot;">​</a></h3><h4 id="option-1-recommended-1" tabindex="-1">Option 1 (recommandée) <a class="header-anchor" href="#option-1-recommended-1" aria-label="Permalink to &quot;Option 1 (recommandée) {#option-1-recommended-1}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configuration automatique<br>    Caméra</p></div><p>Vous devez autoriser xDrip à accéder à l&#39;appareil photo du téléphone.<br> Scannez le QR code affiché sur votre téléphone principal.</p><img src="'+a+'" style="zoom:75%;"><p>Il vous sera demandé de confirmer l&#39;importation de ces paramètres (assurez-vous d&#39;importer des paramètres sûrs).</p><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Importer les paramètres eulement des sources de confiance !<br>  Veuillez confirmer l&#39;importation les paramètres suivants :</p><p> paramètre1<br>  paramètre2<br>  paramètre3</p><p>Non  <span style="background-color:gray;color:white;text-align:center;"> Oui </span></p></div><h4 id="option-1-bis-follower-phone-cannot-read-the-qr-code-1" tabindex="-1">Option 1 bis (le téléphone abonné ne peut pas lire le QR code) <a class="header-anchor" href="#option-1-bis-follower-phone-cannot-read-the-qr-code-1" aria-label="Permalink to &quot;Option 1 bis (le téléphone abonné ne peut pas lire le QR code) {#option-1-bis-follower-phone-cannot-read-the-qr-code-1}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configuration automatique<br>    Fichier image</p></div><p>Sélectionnez l&#39;image contenant le QR code.</p><img src="'+s+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Importer les paramètres eulement des sources de confiance !<br>  Veuillez confirmer l&#39;importation les paramètres suivants :</p><p> paramètre1<br>  paramètre2<br>  paramètre3</p><p>Non  <span style="background-color:gray;color:white;text-align:center;"> Oui </span></p></div><h4 id="option-2-complicated-1" tabindex="-1">Option 2 (compliquée) <a class="header-anchor" href="#option-2-complicated-1" aria-label="Permalink to &quot;Option 2 (compliquée) {#option-2-complicated-1}&quot;">​</a></h4><p>Modifiez le champ de la clé et saisissez <strong>exactement</strong> la même clé que sur le principal.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip+ Synchronisation</p><p>    <strong>Clé de sécurité de groupe de dispositifs</strong></p></div><img src="'+r+'" style="zoom:75%;"><br><h2 id="follower-actions" tabindex="-1">Actions des abonnés <a class="header-anchor" href="#follower-actions" aria-label="Permalink to &quot;Actions des abonnés {#follower-actions}&quot;">​</a></h2><p>Par défaut, les abonnés peuvent envoyer au principal des traitements, des étalonnages et même des démarrages ou arrêts de capteur.<br> Si vous voulez l&#39;empêcher, désactivez <a href="./sync.html#accept-followers-actions">Accepter les actions des Abonnés</a> sur le principal.</p><h2 id="verify" tabindex="-1">Vérifier <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Vérifier {#verify}&quot;">​</a></h2><p>Pour vérifier que l&#39;abonné reçoit bien les données, consultez <a href="./../troubleshoot/systemstatus.html#xdrip-sync-follower">État du système</a> sur le téléphone abonné.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',59)])])}const D=p(m,[["render",u]]);export{k as __pageData,D as default};
